# characters.py: adds a "People" coloring group (Superhero, Princess, Astronaut, Robot, Pirate) and a Fill/Draw (bucket/pencil) toggle to the Coloring Book.
import base64, hashlib, os, sys
FULL = {'app/src/playzone/coloringPages.ts': ('', '3e5842f4a8d57f6941e01bed0100b4b6'), 'app/src/playzone/ColoringBook.tsx': ('', '0984a85df0fec18de08a444f782909ad'), 'app/e2e/art-library.spec.ts': ('', '19e7b242e4926d937e9057135e261576')}
for p, (b, orig) in FULL.items():
    if hashlib.md5(open(p, 'rb').read()).hexdigest() != orig:
        sys.exit(p + ' changed since staging; not applying')
for p, (b, _) in FULL.items():
    open(p, 'wb').write(base64.b64decode(b)); print('wrote', p)
